{
  "analysis": "QEMU 8.2.2 is now installed with both qemu-system-i386 and qemu-system-x86_64. noVNC is available at /usr/share/novnc, websockify is available, and nginx has a default site on port 80. Nothing is running yet. I need to configure nginx to serve noVNC and proxy WebSocket connections to websockify, start QEMU with snapshot mode/VNC :1/monitor socket, start websockify, and start nginx.",
  "plan": "Create an nginx site that serves noVNC from /usr/share/novnc and proxies /websockify to a local websockify instance on port 6080. Create an auto-connect noVNC index page. Launch QEMU with: qemu-system-i386, the disk image in snapshot mode, VNC on 0.0.0.0:1 (port 5901), a Unix monitor socket at /tmp/qemu-monitor.sock for programmatic keyboard input, and daemonize. Then start websockify bridging 127.0.0.1:6080 to 127.0.0.1:5901, test and start nginx.",
  "commands": [
    {
      "keystrokes": "cat > /etc/nginx/sites-available/default << 'EOF'
server {
    listen 80 default_server;

    root /usr/share/novnc;
    index index.html vnc.html;

    server_name _;

    location / {
        try_files $uri $uri/ =404;
    }

    location /websockify {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 86400;
    }
}
EOF
",
      "duration": 0.1
    },
    {
      "keystrokes": "cat > /usr/share/novnc/index.html << 'EOF'
<!DOCTYPE html>
<html>
<head>
<meta http-equiv="refresh" content="0; url=vnc.html?autoconnect=1&resize=scale&path=websockify">
<title>Windows 3.11 noVNC</title>
</head>
<body>Redirecting to noVNC...</body>
</html>
EOF
",
      "duration": 0.1
    },
    {
      "keystrokes": "rm -f /tmp/qemu-monitor.sock /tmp/qemu.pid
qemu-system-i386 \
  -drive file=/app/isos/win311.img,format=raw,if=ide \
  -snapshot \
  -m 32 \
  -vnc 0.0.0.0:1 \
  -monitor unix:/tmp/qemu-monitor.sock,server,nowait \
  -pidfile /tmp/qemu.pid \
  -boot c \
  -daemonize
echo "QEMU exit code: $?"
",
      "duration": 2.0
    },
    {
      "keystrokes": "nohup websockify 127.0.0.1:6080 127.0.0.1:5901 > /tmp/websockify.log 2>&1 &
echo "websockify PID: $!"
",
      "duration": 1.0
    },
    {
      "keystrokes": "nginx -t 2>&1 && nginx
echo "nginx exit code: $?"
",
      "duration": 1.0
    }
  ]
}
